  "id": "foo-bar-paginated-analytics-api",
  "title": "Foo Bar Paginated Analytics API",
  "description": "Build a paginated analytics API that serves large result sets from ClickHouse with cursor-based or offset pagination. Support page size and consistent ordering.",
  "lede": "In this scenario, an agent must build a paginated analytics API that serves large result sets with consistent ordering.",
  "tier": "tier-2",
  "domain": "foo-bar",
  "harness": "classic-de",
  "tasks": [
    {
      "id": "build-paginated-api",
      "description": "Implement an HTTP API with /api/events that supports limit, offset (or cursor), and returns total count.",
      "category": "schema-design"
    }
  ],
  "personaPrompts": {
    "baseline": "prompts/baseline.md",
    "informed": "prompts/informed.md"
  },
  "infrastructure": {
    "services": [
      "clickhouse"
    ],
    "description": "ClickHouse seeded with 10k+ events. Build an API on port 3000 with pagination support."
  },
  "tags": [
    "api",
    "pagination",
    "scalability",
    "performance"
  ],
  "baselineMetrics": {
    "queryLatencyMs": 2000,
    "storageBytes": 50000000,
    "costPerQueryUsd": 0.01
  },
  "referenceMetrics": {
    "queryLatencyMs": 150,
    "storageBytes": 50000000,
    "costPerQueryUsd": 0.002
  }
}

