import http from "node:http";
import { URL } from "node:url";

const PORT = Number.parseInt(process.env.PORT ?? "3000", 10);

function requireClickhouseUrl() {
  const raw = process.env.CLICKHOUSE_URL;
  if (!raw || !String(raw).trim()) {
    throw new Error("CLICKHOUSE_URL is required");
  }
  return String(raw).trim().replace(/\/$/, "");
}

async function clickhouseJson(sql) {
  const base = requireClickhouseUrl();
  const endpoint = new URL(base);
  endpoint.searchParams.set("query", sql);
  const res = await fetch(endpoint.toString(), { method: "POST" });
  if (!res.ok) {
    const text = await res.text();
    throw new Error(`ClickHouse HTTP ${res.status}: ${text.slice(0, 500)}`);
  }
  return res.json();
}

function parsePagination(url) {
  const limitRaw = url.searchParams.get("limit");
  const offsetRaw = url.searchParams.get("offset");
  const limit = Math.min(
    Math.max(Number.parseInt(limitRaw ?? "50", 10) || 50, 1),
    1000,
  );
  const offset = Math.max(Number.parseInt(offsetRaw ?? "0", 10) || 0, 0);
  return { limit, offset };
}

const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url ?? "/", `http://${req.headers.host ?? "localhost"}`);

    if (req.method === "GET" && url.pathname === "/api/events") {
      const { limit, offset } = parsePagination(url);

      const countSql =
        "SELECT count() AS c FROM analytics.events FORMAT JSON";
      const rowsSql =
        "SELECT event_id, event_ts, event_type, user_id FROM analytics.events " +
        "ORDER BY event_ts ASC, event_id ASC " +
        `LIMIT ${limit} OFFSET ${offset} FORMAT JSON`;

      const [countPayload, rowsPayload] = await Promise.all([
        clickhouseJson(countSql),
        clickhouseJson(rowsSql),
      ]);

      const total = Number(countPayload?.data?.[0]?.c ?? 0);
      const data = rowsPayload?.data ?? [];

      res.writeHead(200, { "Content-Type": "application/json; charset=utf-8" });
      res.end(
        JSON.stringify({
          data,
          total,
          limit,
          offset,
        }),
      );
      return;
    }

    res.writeHead(404, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ error: "Not found" }));
  } catch (err) {
    console.error(err);
    res.writeHead(500, { "Content-Type": "application/json" });
    res.end(
      JSON.stringify({
        error: err instanceof Error ? err.message : "Internal error",
      }),
    );
  }
});

server.listen(PORT, "0.0.0.0", () => {
  console.log(`events API listening on ${PORT}`);
});

